1	import { dataValida, diferencaMeses, mesDe, somarMeses, ultimoDia } from './date';
2	import { novoId, proximoTempo } from './id';
3	import {
4	  falha,
5	  ok,
6	  type AppState,
7	  type Ativo,
8	  type Centavos,
9	  type ClasseAtivo,
10	  type DataISO,
11	  type Mes,
12	  type MovimentoAtivo,
13	  type Resultado,
14	} from './types';
15	
16	export const ATIVO_NOME_MAX = 40;
17	export const MESES_EVOLUCAO = 12;
18	
19	export const CLASSES: { valor: ClasseAtivo; rotulo: string }[] = [
20	  { valor: 'renda-fixa', rotulo: 'Renda fixa' },
21	  { valor: 'acoes', rotulo: 'Ações' },
22	  { valor: 'fundos', rotulo: 'Fundos' },
23	  { valor: 'cripto', rotulo: 'Cripto' },
24	  { valor: 'outros', rotulo: 'Outros' },
25	];
26	
27	export const rotuloClasse = (classe: ClasseAtivo): string => CLASSES.find((c) => c.valor === classe)?.rotulo ?? classe;
28	
29	export interface DadosAtivo {
30	  nome: string;
31	  classe: ClasseAtivo;
32	}
33	
34	export interface DadosMovimento {
35	  tipo: 'aporte' | 'resgate';
36	  data: DataISO;
37	  valor: Centavos;
38	}
39	
40	export interface DadosMarcacao {
41	  data: DataISO;
42	  valor: Centavos;
43	}
44	
45	export interface Desempenho {
46	  investido: Centavos;
47	  valorAtual: Centavos;
48	  rentabilidade: Centavos;
49	  /** Percentual com uma casa decimal sobre o investido líquido; null sem investido. */
50	  rentabilidadePct: number | null;
51	}
52	
53	export interface FatiaClasse {
54	  classe: ClasseAtivo;
55	  valor: Centavos;
56	  /** Percentual com uma casa decimal; a soma das fatias é 100. */
57	  pct: number;
58	}
59	
60	export interface PontoPatrimonio {
61	  mes: Mes;
62	  valor: Centavos;
63	}
64	
65	const porData = <T extends { data: DataISO; id: string }>(a: T, b: T) => (a.data < b.data ? -1 : a.data > b.data ? 1 : 0);
66	const delta = (m: MovimentoAtivo): Centavos => (m.tipo === 'aporte' ? m.valor : -m.valor);
67	
68	/** Investido líquido (aportes menos resgates) até `ate`, inclusive. */
69	export function investidoEm(ativo: Ativo, ate?: DataISO): Centavos {
70	  return ativo.movimentos.filter((m) => ate === undefined || m.data <= ate).reduce((s, m) => s + delta(m), 0);
71	}
72	
73	/** Valor da última marcação até `ate` mais o líquido movimentado depois dela; sem marcação, o investido. */
74	export function valorEm(ativo: Ativo, ate?: DataISO): Centavos {
75	  const marcacoes = ativo.marcacoes.filter((m) => ate === undefined || m.data <= ate).sort(porData);
76	  const ultima = marcacoes[marcacoes.length - 1];
77	  if (!ultima) return investidoEm(ativo, ate);
78	  const depois = ativo.movimentos.filter((m) => m.data > ultima.data && (ate === undefined || m.data <= ate));
79	  return ultima.valor + depois.reduce((s, m) => s + delta(m), 0);
80	}
81	
82	/** Arredonda para uma casa decimal. */
83	const umaCasa = (x: number) => Math.round(x * 10) / 10;
84	
85	export function desempenho(investido: Centavos, valorAtual: Centavos): Desempenho {
86	  const rentabilidade = valorAtual - investido;
87	  return { investido, valorAtual, rentabilidade, rentabilidadePct: investido > 0 ? umaCasa((rentabilidade * 100) / investido) : null };
88	}
89	
90	export const desempenhoAtivo = (ativo: Ativo, ate?: DataISO): Desempenho => desempenho(investidoEm(ativo, ate), valorEm(ativo, ate));
91	
92	export function desempenhoCarteira(ativos: Ativo[], ate?: DataISO): Desempenho {
93	  return desempenho(
94	    ativos.reduce((s, a) => s + investidoEm(a, ate), 0),
95	    ativos.reduce((s, a) => s + valorEm(a, ate), 0),
96	  );
97	}
98	
99	/** Alocação por classe com percentuais em décimos que somam exatamente 100,0 (maiores restos). */
100	export function alocacaoPorClasse(ativos: Ativo[], ate?: DataISO): FatiaClasse[] {
101	  const totais = new Map<ClasseAtivo, Centavos>();
102	  for (const a of ativos) totais.set(a.classe, (totais.get(a.classe) ?? 0) + valorEm(a, ate));
103	  const fatias = CLASSES.map((c) => ({ classe: c.valor, valor: totais.get(c.valor) ?? 0 })).filter((f) => f.valor > 0);
104	  const total = fatias.reduce((s, f) => s + f.valor, 0);
105	  if (total === 0) return [];
106	  const brutos = fatias.map((f) => (f.valor * 1000) / total);
107	  const decimos = brutos.map(Math.floor);
108	  let faltam = 1000 - decimos.reduce((s, d) => s + d, 0);
109	  const ordem = brutos.map((b, i) => ({ i, resto: b - decimos[i] })).sort((x, y) => y.resto - x.resto || x.i - y.i);
110	  for (const { i } of ordem) {
111	    if (faltam <= 0) break;
112	    decimos[i] += 1;
113	    faltam -= 1;
114	  }
115	  return fatias.map((f, i) => ({ ...f, pct: decimos[i] / 10 })).sort((a, b) => b.valor - a.valor);
116	}
117	
118	/** Patrimônio no fim de cada mês, dos últimos `MESES_EVOLUCAO` meses a partir do primeiro movimento. */
119	export function evolucaoPatrimonio(ativos: Ativo[], hoje: DataISO): PontoPatrimonio[] {
120	  const datas = ativos.flatMap((a) => a.movimentos.map((m) => m.data));
121	  if (datas.length === 0) return [];
122	  const mesHoje = mesDe(hoje);
123	  const primeiro = mesDe(datas.reduce((a, b) => (a < b ? a : b)));
124	  const inicio = diferencaMeses(primeiro, mesHoje) >= MESES_EVOLUCAO ? somarMeses(mesHoje, -(MESES_EVOLUCAO - 1)) : primeiro;
125	  const pontos: PontoPatrimonio[] = [];
126	  for (let mes = inicio; mes <= mesHoje; mes = somarMeses(mes, 1)) {
127	    const fim = mes === mesHoje ? hoje : ultimoDia(mes);
128	    pontos.push({ mes, valor: ativos.reduce((s, a) => s + valorEm(a, fim), 0) });
129	  }
130	  return pontos;
131	}
132	
133	/** Menor posição acumulada ao longo do tempo; negativa significa resgate sem saldo. */
134	function posicaoMinima(movimentos: MovimentoAtivo[]): Centavos {
135	  // No mesmo dia os aportes contam antes dos resgates.
136	  const ordenados = [...movimentos].sort((a, b) => (a.data === b.data ? (a.tipo === b.tipo ? 0 : a.tipo === 'aporte' ? -1 : 1) : a.data < b.data ? -1 : 1));
137	  let soma = 0;
138	  let minimo = 0;
139	  for (const m of ordenados) {
140	    soma += delta(m);
141	    minimo = Math.min(minimo, soma);
142	  }
143	  return minimo;
144	}
145	
146	function validarData(data: string, hoje: DataISO): Resultado<void> {
147	  if (!dataValida(data)) return falha('Informe uma data válida.', 'data');
148	  if (data > hoje) return falha('A data não pode ser futura.', 'data');
149	  return ok(undefined);
150	}
151	
152	const validarValor = (valor: number): Resultado<void> =>
153	  Number.isSafeInteger(valor) && valor > 0 ? ok(undefined) : falha('O valor deve ser maior que zero.', 'valor');
154	
155	export function validarDadosAtivo(estado: AppState, dados: DadosAtivo): Resultado<DadosAtivo> {
156	  const nome = dados.nome.trim();
157	  if (!nome) return falha('Informe o nome do ativo.', 'nome');
158	  if (nome.length > ATIVO_NOME_MAX) return falha(`O nome deve ter no máximo ${ATIVO_NOME_MAX} caracteres.`, 'nome');
159	  if (!CLASSES.some((c) => c.valor === dados.classe)) return falha('Escolha a classe do ativo.', 'classe');
160	  if (estado.investimentos.some((a) => a.nome.toLowerCase() === nome.toLowerCase())) return falha('Já existe um ativo com esse nome.', 'nome');
161	  return ok({ nome, classe: dados.classe });
162	}
163	
164	export function criarAtivo(estado: AppState, dados: DadosAtivo): Resultado<AppState> {
165	  const v = validarDadosAtivo(estado, dados);
166	  if (!v.ok) return v;
167	  const ativo: Ativo = { id: novoId(), ...v.valor, movimentos: [], marcacoes: [], criadoEm: proximoTempo() };
168	  return ok({ ...estado, investimentos: [...estado.investimentos, ativo] });
169	}
170	
171	export function excluirAtivo(estado: AppState, ativoId: string): Resultado<AppState> {
172	  if (!estado.investimentos.some((a) => a.id === ativoId)) return falha('Ativo não encontrado.');
173	  return ok({ ...estado, investimentos: estado.investimentos.filter((a) => a.id !== ativoId) });
174	}
175	
176	function atualizarAtivo(estado: AppState, ativoId: string, f: (a: Ativo) => Resultado<Ativo>): Resultado<AppState> {
177	  const ativo = estado.investimentos.find((a) => a.id === ativoId);
178	  if (!ativo) return falha('Ativo não encontrado.');
179	  const r = f(ativo);
180	  if (!r.ok) return r;
181	  return ok({ ...estado, investimentos: estado.investimentos.map((a) => (a.id === ativoId ? r.valor : a)) });
182	}
183	
184	export function registrarMovimento(estado: AppState, ativoId: string, dados: DadosMovimento, hoje: DataISO): Resultado<AppState> {
185	  return atualizarAtivo(estado, ativoId, (ativo) => {
186	    if (dados.tipo !== 'aporte' && dados.tipo !== 'resgate') return falha('Escolha aporte ou resgate.', 'tipo');
187	    const vv = validarValor(dados.valor);
188	    if (!vv.ok) return vv;
189	    const vd = validarData(dados.data, hoje);
190	    if (!vd.ok) return vd;
191	    const movimentos = [...ativo.movimentos, { id: novoId(), tipo: dados.tipo, data: dados.data, valor: dados.valor }];
192	    if (posicaoMinima(movimentos) < 0) return falha('O resgate é maior que a posição do ativo nessa data.', 'valor');
193	    return ok({ ...ativo, movimentos });
194	  });
195	}
196	
197	export function registrarMarcacao(estado: AppState, ativoId: string, dados: DadosMarcacao, hoje: DataISO): Resultado<AppState> {
198	  return atualizarAtivo(estado, ativoId, (ativo) => {
199	    const vv = validarValor(dados.valor);
200	    if (!vv.ok) return vv;
201	    const vd = validarData(dados.data, hoje);
202	    if (!vd.ok) return vd;
203	    const outras = ativo.marcacoes.filter((m) => m.data !== dados.data);
204	    return ok({ ...ativo, marcacoes: [...outras, { id: novoId(), data: dados.data, valor: dados.valor }] });
205	  });
206	}
207	
208	export function excluirMovimento(estado: AppState, ativoId: string, movimentoId: string): Resultado<AppState> {
209	  return atualizarAtivo(estado, ativoId, (ativo) => {
210	    const movimentos = ativo.movimentos.filter((m) => m.id !== movimentoId);
211	    if (movimentos.length === ativo.movimentos.length) return falha('Movimento não encontrado.');
212	    if (posicaoMinima(movimentos) < 0) return falha('Não é possível excluir: a posição ficaria negativa em alguma data.');
213	    return ok({ ...ativo, movimentos });
214	  });
215	}
216	
217	export function excluirMarcacao(estado: AppState, ativoId: string, marcacaoId: string): Resultado<AppState> {
218	  return atualizarAtivo(estado, ativoId, (ativo) => {
219	    const marcacoes = ativo.marcacoes.filter((m) => m.id !== marcacaoId);
220	    if (marcacoes.length === ativo.marcacoes.length) return falha('Marcação não encontrada.');
221	    return ok({ ...ativo, marcacoes });
222	  });
223	}
