1	import { novoId, proximoTempo } from './id';
2	import { falha, ok, type AppState, type CartaoConfig, type Centavos, type Conta, type Resultado, type TipoConta, type Transacao } from './types';
3	
4	export const TIPOS_CONTA: TipoConta[] = ['corrente', 'poupanca', 'dinheiro', 'investimento', 'cartao'];
5	
6	export const ROTULO_TIPO_CONTA: Record<TipoConta, string> = {
7	  corrente: 'Conta corrente',
8	  poupanca: 'Poupança',
9	  dinheiro: 'Dinheiro',
10	  investimento: 'Investimento',
11	  cartao: 'Cartão de crédito',
12	};
13	
14	export const NOME_MAX = 40;
15	
16	export interface DadosConta {
17	  nome: string;
18	  tipo: TipoConta;
19	  saldoInicial: Centavos;
20	  /** Ciclo e limite; só vale para o tipo cartão e é opcional até o usuário configurar. */
21	  cartao?: CartaoConfig;
22	}
23	
24	const normalizar = (nome: string) => nome.trim().toLocaleLowerCase('pt-BR');
25	
26	export function validarNomeConta(contas: Conta[], nome: string, ignorarId?: string): Resultado<string> {
27	  const limpo = nome.trim();
28	  if (!limpo) return falha('Informe o nome da conta.', 'nome');
29	  if (limpo.length > NOME_MAX) return falha(`O nome deve ter no máximo ${NOME_MAX} caracteres.`, 'nome');
30	  const duplicada = contas.some((c) => !c.arquivada && c.id !== ignorarId && normalizar(c.nome) === normalizar(limpo));
31	  if (duplicada) return falha('Já existe uma conta ativa com esse nome.', 'nome');
32	  return ok(limpo);
33	}
34	
35	/** Dias de 1 a 28 e limite maior que zero. O campo do erro indica qual valor corrigir. */
36	export function validarCartao(c: CartaoConfig): Resultado<CartaoConfig> {
37	  const diaOk = (d: number) => Number.isInteger(d) && d >= 1 && d <= 28;
38	  if (!diaOk(c.diaFechamento)) return falha('O dia de fechamento deve ser um inteiro de 1 a 28.', 'diaFechamento');
39	  if (!diaOk(c.diaVencimento)) return falha('O dia de vencimento deve ser um inteiro de 1 a 28.', 'diaVencimento');
40	  if (!Number.isInteger(c.limite) || c.limite <= 0) return falha('O limite deve ser maior que zero.', 'limite');
41	  return ok(c);
42	}
43	
44	/** Só contas do tipo cartão guardam configuração de ciclo. */
45	function cartaoDaConta(dados: DadosConta): Resultado<CartaoConfig | undefined> {
46	  if (dados.tipo !== 'cartao' || !dados.cartao) return ok(undefined);
47	  return validarCartao(dados.cartao);
48	}
49	
50	export function criarConta(estado: AppState, dados: DadosConta): Resultado<AppState> {
51	  const nome = validarNomeConta(estado.contas, dados.nome);
52	  if (!nome.ok) return nome;
53	  const cartao = cartaoDaConta(dados);
54	  if (!cartao.ok) return cartao;
55	  const conta: Conta = {
56	    id: novoId(),
57	    nome: nome.valor,
58	    tipo: dados.tipo,
59	    saldoInicial: dados.saldoInicial,
60	    arquivada: false,
61	    criadaEm: proximoTempo(),
62	    ...(cartao.valor ? { cartao: cartao.valor } : {}),
63	  };
64	  return ok({ ...estado, contas: [...estado.contas, conta] });
65	}
66	
67	export function editarConta(estado: AppState, id: string, dados: DadosConta): Resultado<AppState> {
68	  const atual = estado.contas.find((c) => c.id === id);
69	  if (!atual) return falha('Conta não encontrada.');
70	  const nome = atual.arquivada ? ok(dados.nome.trim()) : validarNomeConta(estado.contas, dados.nome, id);
71	  if (!nome.ok) return nome;
72	  if (!nome.valor || nome.valor.length > NOME_MAX) return falha('Nome inválido.', 'nome');
73	  const cartao = cartaoDaConta(dados);
74	  if (!cartao.ok) return cartao;
75	  return ok({
76	    ...estado,
77	    contas: estado.contas.map((c) => {
78	      if (c.id !== id) return c;
79	      const { cartao: _antigo, ...resto } = c;
80	      void _antigo;
81	      return { ...resto, nome: nome.valor, tipo: dados.tipo, saldoInicial: dados.saldoInicial, ...(cartao.valor ? { cartao: cartao.valor } : {}) };
82	    }),
83	  });
84	}
85	
86	export function contaTemTransacoes(estado: AppState, id: string): boolean {
87	  return (
88	    estado.transacoes.some((t) => t.contaId === id) ||
89	    estado.pagamentosFatura.some((p) => p.contaCartaoId === id || p.contaOrigemId === id)
90	  );
91	}
92	
93	/** Só contas sem transações podem ser excluídas; as demais devem ser arquivadas. */
94	export function excluirConta(estado: AppState, id: string): Resultado<AppState> {
95	  if (!estado.contas.some((c) => c.id === id)) return falha('Conta não encontrada.');
96	  if (contaTemTransacoes(estado, id)) return falha('Esta conta tem transações e não pode ser excluída. Arquive-a.');
97	  return ok({ ...estado, contas: estado.contas.filter((c) => c.id !== id) });
98	}
99	
100	export function arquivarConta(estado: AppState, id: string): Resultado<AppState> {
101	  if (!estado.contas.some((c) => c.id === id)) return falha('Conta não encontrada.');
102	  return ok({ ...estado, contas: estado.contas.map((c) => (c.id === id ? { ...c, arquivada: true } : c)) });
103	}
104	
105	export function reativarConta(estado: AppState, id: string): Resultado<AppState> {
106	  const conta = estado.contas.find((c) => c.id === id);
107	  if (!conta) return falha('Conta não encontrada.');
108	  const nome = validarNomeConta(estado.contas, conta.nome, id);
109	  if (!nome.ok) return falha('Já existe uma conta ativa com esse nome. Renomeie uma delas antes de reativar.', 'nome');
110	  return ok({ ...estado, contas: estado.contas.map((c) => (c.id === id ? { ...c, arquivada: false } : c)) });
111	}
112	
113	export function efeitoTransacao(t: Pick<Transacao, 'tipo' | 'valor'>): Centavos {
114	  return t.tipo === 'receita' ? t.valor : -t.valor;
115	}
116	
117	/** Saldo atual: saldo inicial mais receitas menos despesas da conta. Nunca é armazenado. */
118	export function saldoConta(estado: DadosDeSaldo, contaId: string): Centavos {
119	  return saldosPorConta(estado).get(contaId) ?? 0;
120	}
121	
122	type DadosDeSaldo = Pick<AppState, 'contas' | 'transacoes'> & Partial<Pick<AppState, 'pagamentosFatura'>>;
123	
124	export function saldosPorConta(estado: DadosDeSaldo): Map<string, Centavos> {
125	  const saldos = new Map<string, Centavos>(estado.contas.map((c) => [c.id, c.saldoInicial]));
126	  const somar = (contaId: string, valor: Centavos) => {
127	    if (saldos.has(contaId)) saldos.set(contaId, (saldos.get(contaId) ?? 0) + valor);
128	  };
129	  for (const t of estado.transacoes) somar(t.contaId, efeitoTransacao(t));
130	  // Pagar a fatura tira dinheiro da conta de origem e reduz a dívida do cartão.
131	  for (const p of estado.pagamentosFatura ?? []) {
132	    somar(p.contaOrigemId, -p.valor);
133	    somar(p.contaCartaoId, p.valor);
134	  }
135	  return saldos;
136	}
137	
138	export interface SaldoTotal {
139	  /** Soma das contas ativas que não são cartão. */
140	  contas: Centavos;
141	  /** Saldo dos cartões ativos; negativo quando há fatura em aberto. */
142	  cartoes: Centavos;
143	  /** Contas mais cartões (a fatura em aberto é subtraída). */
144	  total: Centavos;
145	}
146	
147	export function saldoTotal(estado: DadosDeSaldo): SaldoTotal {
148	  const saldos = saldosPorConta(estado);
149	  let contas = 0;
150	  let cartoes = 0;
151	  for (const c of estado.contas) {
152	    if (c.arquivada) continue;
153	    const saldo = saldos.get(c.id) ?? 0;
154	    if (c.tipo === 'cartao') cartoes += saldo;
155	    else contas += saldo;
156	  }
157	  return { contas, cartoes, total: contas + cartoes };
158	}
159	
160	/** Ordena por tipo e depois por nome, de forma estável entre recarregamentos. */
161	export function ordenarContas(contas: Conta[]): Conta[] {
162	  return [...contas].sort(
163	    (a, b) => TIPOS_CONTA.indexOf(a.tipo) - TIPOS_CONTA.indexOf(b.tipo) || a.nome.localeCompare(b.nome, 'pt-BR') || a.id.localeCompare(b.id),
164	  );
165	}
