1	export type Centavos = number;
2	/** Data no formato AAAA-MM-DD. */
3	export type DataISO = string;
4	/** Mês no formato AAAA-MM. */
5	export type Mes = string;
6	
7	export type TipoConta = 'corrente' | 'poupanca' | 'dinheiro' | 'cartao' | 'investimento';
8	export type TipoMovimento = 'receita' | 'despesa';
9	
10	/** Ciclo e limite de um cartão de crédito. Dias de 1 a 28 para valerem em todos os meses. */
11	export interface CartaoConfig {
12	  diaFechamento: number;
13	  diaVencimento: number;
14	  limite: Centavos;
15	}
16	
17	export interface Conta {
18	  id: string;
19	  nome: string;
20	  tipo: TipoConta;
21	  saldoInicial: Centavos;
22	  arquivada: boolean;
23	  criadaEm: number;
24	  /** Só para contas do tipo cartão. */
25	  cartao?: CartaoConfig;
26	}
27	
28	export interface Categoria {
29	  id: string;
30	  nome: string;
31	  tipo: TipoMovimento;
32	  arquivada: boolean;
33	}
34	
35	export interface Transacao {
36	  id: string;
37	  contaId: string;
38	  categoriaId: string;
39	  tipo: TipoMovimento;
40	  /** Sempre positivo; o sinal vem do tipo. */
41	  valor: Centavos;
42	  data: DataISO;
43	  descricao: string;
44	  criadaEm: number;
45	  importacaoId?: string;
46	  /** Etiquetas livres, normalizadas (minúsculas); ausente quando não há nenhuma. */
47	  tags?: string[];
