83	/** Juros de um período: `saldo × taxa`, arredondado ao centavo mais próximo (meio para cima), só com inteiros. */
84	function jurosDoPeriodo(saldo: Centavos, taxaBp: number): Centavos {
85	  return Math.floor((saldo * taxaBp + 5000) / 10000);
86	}
87	
88	/** Parcela fixa do sistema Price, calculada uma única vez e arredondada; sem juros, a parte inteira de principal ÷ prazo. */
89	function parcelaPrice({ principal, taxaBp, parcelas }: TermosDivida): Centavos {
90	  if (taxaBp === 0) return Math.floor(principal / parcelas);
91	  const i = taxaBp / 10000;
92	  return Math.round((principal * i) / (1 - Math.pow(1 + i, -parcelas)));
93	}
