95	function calcularParcelas(termos: TermosDivida): Omit<LinhaAmortizacao, 'vencimento'>[] {
96	  const { principal, taxaBp, parcelas, sistema } = termos;
97	  const fixaPrice = sistema === 'price' ? parcelaPrice(termos) : 0;
98	  const fixaSac = Math.floor(principal / parcelas);
99	  const linhas: Omit<LinhaAmortizacao, 'vencimento'>[] = [];
100	  let saldo = principal;
101	  for (let numero = 1; numero <= parcelas; numero++) {
102	    const juros = jurosDoPeriodo(saldo, taxaBp);
103	    const ultima = numero === parcelas;
104	    const previsto = sistema === 'price' ? fixaPrice - juros : fixaSac;
105	    // A última parcela absorve o resto do arredondamento.
106	    const amortizacao = ultima ? saldo : Math.min(Math.max(previsto, 0), saldo);
107	    saldo -= amortizacao;
108	    linhas.push({ numero, juros, amortizacao, parcela: juros + amortizacao, saldo });
109	  }
110	  return linhas;
111	}
