121	/** Tabela de amortização completa da dívida (contratual, sem considerar pagamentos). */
122	export function gerarTabela(d: Pick<Divida, keyof TermosDivida | 'primeiraParcela'>): LinhaAmortizacao[] {
123	  return calcularParcelas(d).map((l) => ({ ...l, vencimento: dataDaParcelaDivida(d.primeiraParcela, l.numero) }));
