130	export function resumoDivida(d: Divida, hoje: DataISO): ResumoDivida {
131	  const tabela = gerarTabela(d);
132	  const pagoDaParcela = (n: number) => somar(d.pagamentos.filter((p) => p.parcela === n).map((p) => p.valor));
133	  const extras = somar(d.pagamentos.filter((p) => p.parcela === undefined).map((p) => p.valor));
134	
135	  const paga = tabela.map((l) => pagoDaParcela(l.numero) >= l.parcela);
136	  const saldoDevedor = Math.max(0, d.principal - somar(tabela.filter((_, i) => paga[i]).map((l) => l.amortizacao)) - extras);
137	  const quitada = saldoDevedor === 0;
138	
139	  const linhas: LinhaSituacao[] = tabela.map((l, i) => {
140	    const pago = pagoDaParcela(l.numero);
141	    const situacao: SituacaoParcela = paga[i] ? 'paga' : !quitada && l.vencimento < hoje ? 'atrasada' : pago > 0 ? 'parcial' : 'pendente';
142	    return { ...l, pago, restante: Math.max(0, l.parcela - pago), situacao };
143	  });
144	  const abertas = quitada ? [] : linhas.filter((l) => l.situacao !== 'paga');
145	  const atrasadas = abertas.filter((l) => l.situacao === 'atrasada');
146	
147	  return {
148	    linhas,
149	    saldoDevedor,
150	    totalJuros: somar(tabela.map((l) => l.juros)),
151	    totalPago: somar(d.pagamentos.map((p) => p.valor)),
152	    quitada,
153	    proxima: abertas[0] ?? null,
154	    atrasadas: { quantidade: atrasadas.length, valor: somar(atrasadas.map((l) => l.restante)) },
155	  };
156	}
