            <th scope="col" className="patrim-grafico__num">Patrimônio líquido</th>
          </tr>
        </thead>
        <tbody>
          {pontos.map((p) => (
            <tr key={p.mes}>
              <th scope="row">{nomeMes(p.mes)}</th>
              <td className="patrim-grafico__num">{formatarMoeda(p.valor)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
